PUNCT_CHARS='\u0600-\u06FFA-Za-z0-9_\u200c'
def token_replace(text, old, new):
    pat=rf'(?<![{PUNCT_CHARS}]){re.escape(old)}(?![{PUNCT_CHARS}])'
    return re.sub(pat,new,text)

changes={}
for ep in range(1,14):
    p=OUT/f'{ep}.md'
    text=p.read_text(encoding='utf-8')
    original=text
    log=[]
    # Longer/specific malformed tokens first.
    for old,new in sorted(GLOBAL.items(), key=lambda kv: len(kv[0]), reverse=True):
        before=text
        text=token_replace(text,old,new)
        n=before.count(old)-text.count(old)
        if n>0: log.append((old,new,n))
    for old,new in EP.get(ep,{}).items():
        n=text.count(old)
        if n:
            text=text.replace(old,new)
            log.append((old,new,n))
    if text!=original:
        p.write_text(text,encoding='utf-8')
    changes[ep]=log

# Permanent concise provenance report (kept only after validation).
lines=['# گزارش پاک‌سازی ASR — خانه تو','',
'دامنه: فقط `outputs/khane_to/review/md/1.md` تا `13.md`.','',
'- هیچ خلاصه‌سازی، حذف محتوا، ادغام دیالوگ یا رسمی‌سازی عامدانه انجام نشده است.',
'- اصلاحات محدود به خطاهای آشکار ASR/املایی و عبارت‌های مخدوشی است که با بافت یا متن مرجع دوم قابل تأیید بوده‌اند.',
'- `[نامفهوم]`هایی که بدون صوت یا مرجع روشن قابل حل نبودند دست‌نخورده مانده‌اند.','']
for ep in range(1,14):
    total=sum(n for _,_,n in changes[ep])
    lines.append(f'## قسمت {ep} — {total} جایگزینی')
    for a,b,n in changes[ep]: lines.append(f'- `{a}` → `{b}` × {n}')
    lines.append('')
REPORT.parent.mkdir(parents=True,exist_ok=True)
REPORT.write_text('\n'.join(lines),encoding='utf-8')
print(json.dumps({str(k):sum(n for _,_,n in v) for k,v in changes.items()},ensure_ascii=False))
